type HttpHeaders = { [header: string]: string };

function setHeader(headers: HttpHeaders, name: string, value: string) {
  headers[name.toLowerCase()] = value;
}

const h: HttpHeaders = {};
setHeader(h, "Content-Type", "application/json");

type Status = "pending" | "done" | "failed";

const labels: Record<Status, string> = {
  pending: "Waiting",
  done: "Complete",
  failed: "Error",
};

function label(s: Status): string {
  return labels[s];
}

const scores: Record<string, number> = { ada: 95 };

function getScore(id: string): number | undefined {
  if (id in scores) {
    return scores[id]; // narrowed when flag on
  }
  return undefined;
}

